// Reviewed Turkish questions from sorular3.docx. See tests/millionaire-sorular3-audit.json.
(()=>{'use strict';window.MILLIONAIRE_BANKS.turkish.push(...[{"id":"tr-s3-001","stage":5,"category":"Kelimede yapı","text":"“Gözlük” sözcüğü hangisinde doğru ayrılmıştır?","answers":["Kök: gözlü, ek: -k","Kök: gö, ek: -zlük","Kök: göz, ek: -lük","Kök: gözlük, ek yok"],"correct":"Kök: göz, ek: -lük","source":"sorular3.docx","sourceLocation":"paragraph 4"},{"id":"tr-s3-002","stage":5,"category":"Kelimede yapı","text":"Hangi sözcüğün kökü fiildir?","answers":["gözlük","tuzluk","okuyucu","kitapçı"],"correct":"okuyucu","source":"sorular3.docx","sourceLocation":"paragraph 7"},{"id":"tr-s3-003","stage":5,"category":"Kelimede yapı","text":"“Okullarımızdan” sözcüğünün kökü ve ek sayısı hangisidir?","answers":["okul – 2 ek","okul – 3 ek","okullar – 3 ek","okul – 4 ek"],"correct":"okul – 3 ek","source":"sorular3.docx","sourceLocation":"paragraph 8"},{"id":"tr-s3-004","stage":5,"category":"Kelimede yapı","text":"“Kitapçılarımızdan” sözcüğünün kökü ve ek sayısı hangisidir?","answers":["kitap – 3 ek","kitapçı – 3 ek","kitap – 4 ek","kitapçılar – 2 ek"],"correct":"kitap – 4 ek","source":"sorular3.docx","sourceLocation":"paragraph 10"},{"id":"tr-s3-005","stage":3,"category":"Şiir ve uyak","text":"“Bahçede açtı bir gül, / Şarkı söyledi bülbül.” Uyaklı sözcükler hangileridir?","answers":["bahçede – şarkı","açtı – söyledi","gül – bülbül","bir – şarkı"],"correct":"gül – bülbül","source":"sorular3.docx","sourceLocation":"paragraph 15"},{"id":"tr-s3-006","stage":3,"category":"Şiir ve uyak","text":"“Elimde kalem, / Gönlümde elem.” Uyaklı sözcükler hangileridir?","answers":["elimde – gönlümde","kalem – elem","elimde – kalem","gönlümde – kalem"],"correct":"kalem – elem","source":"sorular3.docx","sourceLocation":"paragraph 19"},{"id":"tr-s3-007","stage":4,"category":"Şiir ve uyak","text":"“Uzak yollar gözlerimde, / Sıcak sevgi sözlerimde. / Kuşlar uçar yüce dağda, / Güller açar sakin bağda.” Dörtlükteki uyaklı sözcük çiftleri hangileridir?","answers":["yollar – sevgi ve kuşlar – güller","uçar – açar ve yollar – sevgi","gözlerimde – dağda ve sözlerimde – bağda","gözlerimde – sözlerimde ve dağda – bağda"],"correct":"gözlerimde – sözlerimde ve dağda – bağda","source":"sorular3.docx","sourceLocation":"paragraph 20"},{"id":"tr-s3-008","stage":3,"category":"Şiir ve uyak","text":"“Gönül bahçesinde güller açar, / Gül kokusu dört yana saçar.” Uyaklı sözcükler hangileridir?","answers":["gönül – gül","bahçesinde – kokusu","güller – yana","açar – saçar"],"correct":"açar – saçar","source":"sorular3.docx","sourceLocation":"paragraph 22"},{"id":"tr-s3-009","stage":5,"category":"Anlatım bozukluğu","text":"Hangisinde gereksiz sözcük kullanımı vardır?","answers":["Toplantı dörtte başlayacak.","Arkadaşlarımla birlikte beraber tatile çıktık.","Kapıyı yavaşça kapattı.","Sınavı geçti."],"correct":"Arkadaşlarımla birlikte beraber tatile çıktık.","source":"sorular3.docx","sourceLocation":"paragraph 26"},{"id":"tr-s3-010","stage":5,"category":"Anlatım bozukluğu","text":"Hangisinde anlam belirsizliği vardır?","answers":["Ali dün Ahmet’i ziyaret etti.","Ali, Ahmet’i evinde ziyaret etti.","Ali kendi evinde yemek yedi.","Ahmet, Ali’ye kitap verdi."],"correct":"Ali, Ahmet’i evinde ziyaret etti.","source":"sorular3.docx","sourceLocation":"paragraph 30"},{"id":"tr-s3-011","stage":5,"category":"Anlatım bozukluğu","text":"Hangisinde zaman çelişkisi vardır?","answers":["Yarın sabah erken kalkacağım.","Dün akşam sinemaya gitmişler.","Geçen yıl önümüzdeki hafta tatile çıkacağız.","Şimdi yemek yiyorum."],"correct":"Geçen yıl önümüzdeki hafta tatile çıkacağız.","source":"sorular3.docx","sourceLocation":"paragraph 31"},{"id":"tr-s3-012","stage":5,"category":"Anlatım bozukluğu","text":"Hangisinde gereksiz sözcük vardır?","answers":["Çocuklar bahçede oynuyordu.","Kuşlar ağaçta ötüyordu.","Annem akşam yemek pişirdi.","Bütün tüm öğrenciler toplantıdaydı."],"correct":"Bütün tüm öğrenciler toplantıdaydı.","source":"sorular3.docx","sourceLocation":"paragraph 32"},{"id":"tr-s3-013","stage":5,"category":"Anlatım bozukluğu","text":"Hangisinde bağlaç fazlalığı vardır?","answers":["Hastaydı, ama okula geldi.","Hasta olduğu hâlde okula geldi.","Hastaydı, yine de okula geldi.","Hasta olmasına rağmen ama okula geldi."],"correct":"Hasta olmasına rağmen ama okula geldi.","source":"sorular3.docx","sourceLocation":"paragraph 33"},{"id":"tr-s3-014","stage":5,"category":"Anlatım bozukluğu","text":"Hangisinde deyim yanlış kullanılmıştır?","answers":["Sınav sonucu gelince ağzı kulaklarına vardı.","Yalan söyleyene herkes sırtını döndü.","Çok sinirlendiği için ağzı kulaklarına vardı.","Başarısı herkesi gururlandırdı."],"correct":"Çok sinirlendiği için ağzı kulaklarına vardı.","source":"sorular3.docx","sourceLocation":"paragraph 34"},{"id":"tr-s3-015","stage":5,"category":"Anlatım bozukluğu","text":"Hangisinde anlatım bozukluğu vardır?","answers":["Hasta olduğu için gelemedi.","Hasta olduğundan gelemedi.","Hasta olduğu için dolayı gelemedi.","Hastalığı yüzünden gelemedi."],"correct":"Hasta olduğu için dolayı gelemedi.","source":"sorular3.docx","sourceLocation":"paragraph 35"},{"id":"tr-s3-016","stage":4,"category":"Sözcük türleri","text":"Hangisinde belirtme sıfatı vardır?","answers":["Güzel bir elbise aldı.","Bunu aldı.","Elbiseleri yıkadı.","Bu elbise çok güzel."],"correct":"Bu elbise çok güzel.","source":"sorular3.docx","sourceLocation":"paragraph 40"},{"id":"tr-s3-017","stage":4,"category":"Sözcük türleri","text":"Hangisinde niteleme sıfatı vardır?","answers":["Üç kitap aldım.","Şu kitabı ver.","Ağır bir çanta taşıdı.","Hangi kitap?"],"correct":"Ağır bir çanta taşıdı.","source":"sorular3.docx","sourceLocation":"paragraph 41"},{"id":"tr-s3-018","stage":4,"category":"Sözcük türleri","text":"Hangisinde “büyük” sözcüğü sıfat değil, isim yerine kullanılmıştır?","answers":["Büyük ev satıldı.","Büyük bir fırtına çıktı.","Büyük araba geçti.","Büyükler toplantıya girdi."],"correct":"Büyükler toplantıya girdi.","source":"sorular3.docx","sourceLocation":"paragraph 44"},{"id":"tr-s3-019","stage":4,"category":"Sözcük türleri","text":"Hangisinde “bu” sıfat olarak kullanılmıştır?","answers":["Bunu al.","Bu kitabı al.","Bu güzeldi.","Bundan ver."],"correct":"Bu kitabı al.","source":"sorular3.docx","sourceLocation":"paragraph 45"},{"id":"tr-s3-020","stage":4,"category":"Sözcük türleri","text":"Hangisinde “hızlı” sözcüğü sıfattır?","answers":["Hızlı koştu.","Hızlı yürüdü.","Hızlı araba geçti.","Hızlı yazdı."],"correct":"Hızlı araba geçti.","source":"sorular3.docx","sourceLocation":"paragraph 46"},{"id":"tr-s3-021","stage":2,"category":"Sözcük türleri","text":"“Kuşlar dalda ötüyor.” cümlesindeki fiil hangisidir?","answers":["kuşlar","dalda","ötüyor","hiçbiri"],"correct":"ötüyor","source":"sorular3.docx","sourceLocation":"paragraph 51"},{"id":"tr-s3-022","stage":3,"category":"Sözcük türleri","text":"Hangi cümlede iki fiil vardır?","answers":["Ali okula gitti.","Kırmızı bir araba.","Annem yemek yaptı, biz sofrayı kurduk.","Güzel bir gün."],"correct":"Annem yemek yaptı, biz sofrayı kurduk.","source":"sorular3.docx","sourceLocation":"paragraph 52"},{"id":"tr-s3-023","stage":5,"category":"Sözcük türleri","text":"Hangisi oluş bildiren fiildir?","answers":["yazmak","okumak","çizmek","solmak"],"correct":"solmak","source":"sorular3.docx","sourceLocation":"paragraph 55"},{"id":"tr-s3-024","stage":5,"category":"Sözcük türleri","text":"Hangisi durum bildiren fiildir?","answers":["koşmak","oturmak","solmak","çalışmak"],"correct":"oturmak","source":"sorular3.docx","sourceLocation":"paragraph 56"},{"id":"tr-s3-025","stage":3,"category":"Sözcük türleri","text":"Hangisi olumsuz fiildir?","answers":["geldi","gelir","gelecek","gelmedi"],"correct":"gelmedi","source":"sorular3.docx","sourceLocation":"paragraph 57"},{"id":"tr-s3-026","stage":4,"category":"Sözcük türleri","text":"Hangi cümlenin yüklemi fiil değildir?","answers":["Ali koştu.","Kuşlar uçtu.","Hava soğuk.","Annem geldi."],"correct":"Hava soğuk.","source":"sorular3.docx","sourceLocation":"paragraph 58"},{"id":"tr-s3-027","stage":3,"category":"Sözcük türleri","text":"Hangisinde “yüz” sözcüğü fiildir?","answers":["Yüzünü yıka.","Yüz kişi geldi.","Yüzü kızardı.","Denizde yüz."],"correct":"Denizde yüz.","source":"sorular3.docx","sourceLocation":"paragraph 59"},{"id":"tr-s3-028","stage":5,"category":"Kelimede yapı","text":"Hangi grupta tüm sözcükler yapım eki almıştır?","answers":["evler, kalemler, okullar","masa, kalem, defter","evde, okulda, bahçede","kitaplık, gözlük, sütçü"],"correct":"kitaplık, gözlük, sütçü","source":"sorular3.docx","sourceLocation":"paragraph 65"},{"id":"tr-s3-029","stage":5,"category":"Kelimede yapı","text":"Hangisi isimden fiil türetmiştir?","answers":["yazmak","okumak","gelmek","sulamak"],"correct":"sulamak","source":"sorular3.docx","sourceLocation":"paragraph 68"},{"id":"tr-s3-030","stage":5,"category":"Kelimede yapı","text":"Hangisinde iki yapım eki vardır?","answers":["evler","kitapçılık","kalemlik","okulda"],"correct":"kitapçılık","source":"sorular3.docx","sourceLocation":"paragraph 69"},{"id":"tr-s3-031","stage":5,"category":"Kelimede yapı","text":"Hangisinde hem yapım hem çekim eki vardır?","answers":["gözlük","kalemler","gözlükçüler","evler"],"correct":"gözlükçüler","source":"sorular3.docx","sourceLocation":"paragraph 70"},{"id":"tr-s3-032","stage":5,"category":"Kelimede yapı","text":"Hangi eşleştirme yanlıştır? (Parantez içindeki ek yapım eki olarak verilmiştir.)","answers":["göz → gözlük (-lük)","ev → evde (-de)","süt → sütçü (-çü)","tuz → tuzluk (-luk)"],"correct":"ev → evde (-de)","source":"sorular3.docx","sourceLocation":"paragraph 71"},{"id":"tr-s3-033","stage":5,"category":"Kelimede yapı","text":"Hangisinde yalnız çekim ekleri vardır?","answers":["kitapçılar","evlerimiz","gözlükler","sütçüler"],"correct":"evlerimiz","source":"sorular3.docx","sourceLocation":"paragraph 79"},{"id":"tr-s3-034","stage":5,"category":"Kelimede yapı","text":"Çekim eklerinin özelliği hangisidir?","answers":["Yeni anlamlı sözcük türetir.","Kökü değiştirir.","Sözcüğü cümledeki diğer sözcüklere bağlar, anlamını değiştirmez.","Her zaman sözcüğün başına gelir."],"correct":"Sözcüğü cümledeki diğer sözcüklere bağlar, anlamını değiştirmez.","source":"sorular3.docx","sourceLocation":"paragraph 80"},{"id":"tr-s3-035","stage":5,"category":"Kelimede yapı","text":"Hangisi çekim eki değildir?","answers":["-ler","-de","-lik","-i"],"correct":"-lik","source":"sorular3.docx","sourceLocation":"paragraph 82"},{"id":"tr-s3-036","stage":3,"category":"Cümlede anlam","text":"“Hava çok soğuktu. Bu yüzden evden çıkmadık.” cümlesinde “evden çıkmadık” neyi bildirir?","answers":["Sebep","Amaç","Koşul","Sonuç"],"correct":"Sonuç","source":"sorular3.docx","sourceLocation":"paragraph 89"},{"id":"tr-s3-037","stage":3,"category":"Cümlede anlam","text":"Hangisi amaç bildirmez?","answers":["Spor yapmak için erken kalktı.","Sınavı geçmek için çalışıyor.","Yorgun olduğu için eve gitti.","Tatile çıkmak için para biriktirdi."],"correct":"Yorgun olduğu için eve gitti.","source":"sorular3.docx","sourceLocation":"paragraph 91"},{"id":"tr-s3-038","stage":3,"category":"Cümlede anlam","text":"“I. Sağlıklı olmak için spor yapıyor. II. Spor yaptığı için sağlıklı.” Bu cümleler için hangisi doğrudur?","answers":["I amaç, II sebep","I sebep, II amaç","İkisi de amaç","İkisi de sebep"],"correct":"I amaç, II sebep","source":"sorular3.docx","sourceLocation":"paragraph 93"},{"id":"tr-s3-039","stage":3,"category":"Cümlede anlam","text":"Hangisinde koşul vardır?","answers":["Ders çalıştığı için geçti.","Geçmek için çalıştı.","Ders çalışmasaydı sınavı geçemezdi.","Ders çalıştı ama geçemedi."],"correct":"Ders çalışmasaydı sınavı geçemezdi.","source":"sorular3.docx","sourceLocation":"paragraph 94"},{"id":"tr-s3-040","stage":4,"category":"Paragrafta anlam","text":"“Ali her gün yarım saat kitap okur. Bir yılda onlarca kitap bitirmiştir.” Hangisi çıkarılamaz?","answers":["Ali düzenli okur.","Ali bir yılda çok kitap bitirmiştir.","Ali yalnızca roman okur.","Ali’nin okuma alışkanlığı vardır."],"correct":"Ali yalnızca roman okur.","source":"sorular3.docx","sourceLocation":"paragraph 101"},{"id":"tr-s3-041","stage":4,"category":"Paragrafta anlam","text":"“Dijital okuryazarlık, internetteki bilgilerin doğruluğunu sorgulayabilmektir. Her haber gerçeği yansıtmaz.” Hangisi çıkarılamaz?","answers":["Bilgiler sorgulanmalıdır.","Her haber doğru değildir.","İnternetteki tüm haberler yalandır.","Doğruluk kontrol edilebilir."],"correct":"İnternetteki tüm haberler yalandır.","source":"sorular3.docx","sourceLocation":"paragraph 104"},{"id":"tr-s3-042","stage":4,"category":"Paragrafta anlam","text":"“Bu bölgede yazın yağış azdır, kışlar ise yağışlı geçer.” Hangisi çıkarılamaz?","answers":["Kışın yağış fazladır.","Yazın yağış azdır.","Bölgede yıl boyu bol yağış vardır.","Yağış mevsimlere göre değişir."],"correct":"Bölgede yıl boyu bol yağış vardır.","source":"sorular3.docx","sourceLocation":"paragraph 105"},{"id":"tr-s3-043","stage":5,"category":"Paragrafta anlam","text":"“Yazar romanında çocukluk anılarını anlatırken bir köyü ayrıntılı biçimde betimlemiştir. Ancak kitapta kahramanın adı hiç geçmez.” Hangisi çıkarılamaz?","answers":["Roman anıları anlatır.","Köy ayrıntılı betimlenmiştir.","Kahramanın adı verilmemiştir.","Kahramanın adı Ali’dir."],"correct":"Kahramanın adı Ali’dir.","source":"sorular3.docx","sourceLocation":"paragraph 107"},{"id":"tr-s3-044","stage":4,"category":"Çıkarım","text":"“Mert her hafta sonu mahalledeki yaşlılara alışveriş yapıyor. Yaşlılar da her seferinde ona dua ediyor.” Hangisi çıkarılabilir?","answers":["Mert çok zengindir.","Yaşlılar Mert’ten rahatsızdır.","Mert yardımseverdir.","Mert hafta içi alışveriş yapar."],"correct":"Mert yardımseverdir.","source":"sorular3.docx","sourceLocation":"paragraph 111"},{"id":"tr-s3-045","stage":4,"category":"Çıkarım","text":"“Kâğıt, geri dönüşümle yeniden kâğıda dönüştürülebilir. Böylece ağaç kesimi azalır.” Hangisi çıkarılabilir?","answers":["Ağaç kesimi artar.","Kâğıt hiç kullanılmamalıdır.","Geri dönüşüm ağaçların korunmasına yardımcı olur.","Geri dönüşüm pahalıdır."],"correct":"Geri dönüşüm ağaçların korunmasına yardımcı olur.","source":"sorular3.docx","sourceLocation":"paragraph 112"},{"id":"tr-s3-046","stage":4,"category":"Çıkarım","text":"“Hava durumuna göre yarın sağanak yağış bekleniyor. Okul müdürlüğü öğrencilere şemsiye getirmelerini hatırlattı.” Hangisi çıkarılabilir?","answers":["Yarın hava açık olacaktır.","Okul yarın tatildir.","Öğrenciler şemsiyesiz gelmelidir.","Yağış beklendiği için şemsiye getirilmesi istenmiştir."],"correct":"Yağış beklendiği için şemsiye getirilmesi istenmiştir.","source":"sorular3.docx","sourceLocation":"paragraph 113"},{"id":"tr-s3-047","stage":4,"category":"Çıkarım","text":"“Kitabı bitirdiğinde gözleri doldu, uzun süre pencereden dışarı baktı.” Hangisi çıkarılabilir?","answers":["Kitap onu duygulandırmıştır.","Kitap çok komiktir.","Kitap sıkıcıdır.","Pencere kırıktır."],"correct":"Kitap onu duygulandırmıştır.","source":"sorular3.docx","sourceLocation":"paragraph 114"},{"id":"tr-s3-048","stage":4,"category":"Çıkarım","text":"“Sinemada kuyruk çok uzundu; bu yüzden film başlamadan salona giremeyenler oldu.” Hangisi çıkarılabilir?","answers":["Kuyruk kısaydı.","Uzun kuyruk bazı kişilerin filme geç kalmasına yol açtı.","Film iptal edildi.","Herkes zamanında girdi."],"correct":"Uzun kuyruk bazı kişilerin filme geç kalmasına yol açtı.","source":"sorular3.docx","sourceLocation":"paragraph 116"},{"id":"tr-s3-049","stage":4,"category":"Çıkarım","text":"“Öğretmen, ödevini teslim etmeyen öğrencilerin velilerini aradı.” Hangisi çıkarılabilir?","answers":["Bütün öğrenciler ödevini teslim etmiştir.","Öğretmen ödevi iptal etmiştir.","Veliler ödevi yapmıştır.","Öğretmen ödev teslimine önem veriyor."],"correct":"Öğretmen ödev teslimine önem veriyor.","source":"sorular3.docx","sourceLocation":"paragraph 118"},{"id":"tr-s3-050","stage":5,"category":"Çıkarım","text":"“Zeynep’in bahçesindeki elma ağaçları bu yıl hiç meyve vermedi. Komşusunun aynı türdeki ağaçları ise çok verimli oldu.” Hangisi çıkarılabilir?","answers":["Zeynep ağaçlarını sulamamıştır.","Elma ağaçları meyve vermez.","Komşunun ağaçları ilaçlanmıştır.","Zeynep’in ağaçları bu yıl komşunun ağaçlarından daha az verimli olmuştur."],"correct":"Zeynep’in ağaçları bu yıl komşunun ağaçlarından daha az verimli olmuştur.","source":"sorular3.docx","sourceLocation":"paragraph 119"},{"id":"tr-s3-051","stage":4,"category":"Metin yapıları","text":"“Mehmet sabah erkenden kalktı, kahvaltısını yaptı ve okula yürüdü. Yolda arkadaşıyla karşılaştı.” Bu parçada hangi anlatım biçimi vardır?","answers":["Betimleme","Öyküleme","Açıklama","Tartışma"],"correct":"Öyküleme","source":"sorular3.docx","sourceLocation":"paragraph 122"},{"id":"tr-s3-052","stage":4,"category":"Metin yapıları","text":"Hangisinde öyküleme vardır?","answers":["Gökyüzü masmaviydi, bulutlar pamuk gibiydi.","Su, sıfır derecede donar.","Bence tatil uzun olmalı.","Kapıyı açtı, içeri girdi ve ışığı yaktı."],"correct":"Kapıyı açtı, içeri girdi ve ışığı yaktı.","source":"sorular3.docx","sourceLocation":"paragraph 126"},{"id":"tr-s3-053","stage":4,"category":"Metin yapıları","text":"Hangisinde betimleme vardır?","answers":["Uzun boylu, kumral saçlı, gözlüklü bir adamdı.","Sabah kalktı, okula gitti.","Ay, Dünya’nın uydusudur.","Bence bu karar yanlış."],"correct":"Uzun boylu, kumral saçlı, gözlüklü bir adamdı.","source":"sorular3.docx","sourceLocation":"paragraph 127"},{"id":"tr-s3-054","stage":3,"category":"Yazım kuralları","text":"Hangisinde “-de” bulunma eki olarak bitişik yazılmıştır?","answers":["Ali de geldi.","Sen de gel.","Ayşe de güldü.","Okulda toplandık."],"correct":"Okulda toplandık.","source":"sorular3.docx","sourceLocation":"paragraph 135"},{"id":"tr-s3-055","stage":3,"category":"Yazım kuralları","text":"Hangisinde bağlaç olan “ki” kullanılmıştır?","answers":["Çantadaki kitap","Evdeki ses","Sınıftaki öğrenci","Öyle yoruldum ki hemen uyudum."],"correct":"Öyle yoruldum ki hemen uyudum.","source":"sorular3.docx","sourceLocation":"paragraph 138"},{"id":"tr-s3-056","stage":3,"category":"Noktalama","text":"Diyalog (konuşma) metinlerinde konuşma çizgisi olarak hangisi kullanılır?","answers":["Eğik çizgi","Kesme işareti","Uzun çizgi","İki nokta"],"correct":"Uzun çizgi","source":"sorular3.docx","sourceLocation":"paragraph 154"},{"id":"tr-s3-057","stage":6,"category":"Ses bilgisi","text":"“kitap → kitabı” sözcüğünde hangi ses olayı vardır?","answers":["Ünsüz benzeşmesi","Ünsüz yumuşaması","Ünlü düşmesi","Ünlü daralması"],"correct":"Ünsüz yumuşaması","source":"sorular3.docx","sourceLocation":"paragraph 158"},{"id":"tr-s3-058","stage":6,"category":"Ses bilgisi","text":"Hangisinde ünsüz yumuşaması yoktur?","answers":["kanat → kanadı","çocuk → çocuğu","ağaç → ağacı","kalem → kalemi"],"correct":"kalem → kalemi","source":"sorular3.docx","sourceLocation":"paragraph 162"},{"id":"tr-s3-059","stage":6,"category":"Ses bilgisi","text":"Hangisinde kaynaştırma ünsüzü vardır?","answers":["evi","okulu","masayı","kitabı"],"correct":"masayı","source":"sorular3.docx","sourceLocation":"paragraph 166"},{"id":"tr-s3-060","stage":6,"category":"Ses bilgisi","text":"Hangi grupta yalnızca ünlü düşmesi örnekleri vardır?","answers":["kitap–kitabı, ağaç–ağacı","ağız–ağzı, omuz–omzu, burun–burnu","ev–evi, masa–masayı","gitti, bekliyor"],"correct":"ağız–ağzı, omuz–omzu, burun–burnu","source":"sorular3.docx","sourceLocation":"paragraph 167"},{"id":"tr-s3-061","stage":10,"category":"Çıkarım","text":"“Yağmur yağarsa maç ertelenir. Maç ertelenmedi.” Hangisi kesin doğrudur?","answers":["Yağmur yağmıştır.","Maç yarın yapılacaktır.","Hava güneşliydi.","Yağmur yağmamıştır."],"correct":"Yağmur yağmamıştır.","source":"sorular3.docx","sourceLocation":"paragraph 172"},{"id":"tr-s3-062","stage":8,"category":"Çıkarım","text":"“Ayşe, Ali ile aynı şehirde oturuyor. Ali Ankara’da oturuyor.” Hangisi kesin doğrudur?","answers":["Ayşe İzmir’de oturur.","Ayşe Ankara’da oturur.","Ali, Ayşe’nin kardeşidir.","Ali İzmir’e taşınacak."],"correct":"Ayşe Ankara’da oturur.","source":"sorular3.docx","sourceLocation":"paragraph 173"},{"id":"tr-s3-063","stage":8,"category":"Çıkarım","text":"“Yalnızca çalışkan öğrenciler ödül alacaktır. Deniz ödül aldı.” Hangisi kesin doğrudur?","answers":["Deniz tembeldir.","Bütün çalışkan öğrenciler ödül almıştır.","Deniz çalışkandır.","Ödül verilmemiştir."],"correct":"Deniz çalışkandır.","source":"sorular3.docx","sourceLocation":"paragraph 178"},{"id":"tr-s3-064","stage":6,"category":"Yorumlama","text":"“Gökyüzüne bakıp yıldızları saymak istedi; ama önce ayağının altındaki taşı görmesi gerekiyordu.” Bu sözle ne anlatılmak istenir?","answers":["Yıldızlar sayılamaz.","Taşlar tehlikelidir.","Büyük hedeflere ulaşırken yakınımızdaki engelleri de görmeliyiz.","Gökyüzüne bakmak yasaktır."],"correct":"Büyük hedeflere ulaşırken yakınımızdaki engelleri de görmeliyiz.","source":"sorular3.docx","sourceLocation":"paragraph 182"},{"id":"tr-s3-065","stage":6,"category":"Yorumlama","text":"Fidan, “Büyümek için önce toprağa tutunmalıyım.” dedi. Anlatılmak istenen nedir?","answers":["Fidanlar konuşur.","Toprak değerlidir.","Gelişmek için önce sağlam bir temel gerekir.","Ağaçlar sulanmalıdır."],"correct":"Gelişmek için önce sağlam bir temel gerekir.","source":"sorular3.docx","sourceLocation":"paragraph 183"},{"id":"tr-s3-066","stage":6,"category":"Yorumlama","text":"“Küçük bir damla bile denize katıldığında okyanusun parçası olur.” Bu sözle ne anlatılmak istenir?","answers":["Denizler çok büyüktür.","Küçük katkılar da büyük bütünün bir parçası olur.","Damlalar yok olur.","Okyanus tuzludur."],"correct":"Küçük katkılar da büyük bütünün bir parçası olur.","source":"sorular3.docx","sourceLocation":"paragraph 184"},{"id":"tr-s3-067","stage":6,"category":"Yorumlama","text":"“Kitaplar, raflarda bekleyen sessiz dostlardır.” Bu sözle ne anlatılmak istenir?","answers":["Kitaplar rafta durur.","Kitaplar konuşabilir.","Kitaplar, okuyana arkadaşlık ve bilgi sunar.","Dostlar sessizdir."],"correct":"Kitaplar, okuyana arkadaşlık ve bilgi sunar.","source":"sorular3.docx","sourceLocation":"paragraph 185"},{"id":"tr-s3-068","stage":6,"category":"Yorumlama","text":"“Zaman, tutulmayan bir ırmak gibi akar.” Bu sözle ne anlatılmak istenir?","answers":["Irmaklar hızlı akar.","Zaman geri gelmez, bu yüzden değerlidir.","Zaman ölçülemez.","Irmaklar tutulamaz."],"correct":"Zaman geri gelmez, bu yüzden değerlidir.","source":"sorular3.docx","sourceLocation":"paragraph 186"},{"id":"tr-s3-069","stage":6,"category":"Yorumlama","text":"“Güzel söz, kapalı kapıları açar.” Bu sözle ne anlatılmak istenir?","answers":["Kapılar sözle açılır.","Konuşmak yasaktır.","Kapılar kilitlidir.","Nazik ve tatlı konuşmak, zor durumları kolaylaştırır."],"correct":"Nazik ve tatlı konuşmak, zor durumları kolaylaştırır.","source":"sorular3.docx","sourceLocation":"paragraph 187"},{"id":"tr-s3-070","stage":6,"category":"Yorumlama","text":"“Ali, kırık oyuncağını attı. Babası oyuncağı tamir edip ona geri verdi. Ali o günden sonra eşyalarını atmadı.” Bu öyküden çıkan ders nedir?","answers":["Oyuncaklar kolay kırılır.","Babalar tamirci olmalıdır.","Oyuncak atılmamalıdır.","Eşyaların değerini bilmeli, onarılabilir olanı atmamalıyız."],"correct":"Eşyaların değerini bilmeli, onarılabilir olanı atmamalıyız.","source":"sorular3.docx","sourceLocation":"paragraph 188"},{"id":"tr-s3-071","stage":6,"category":"Yorumlama","text":"“Karınca taşıdığı yükün ağırlığını fark etmeden yoluna devam etti; çünkü hedefini biliyordu.” Bu sözle ne anlatılmak istenir?","answers":["Karıncalar güçlüdür.","Yük ağırdır.","Hedefi olan kişi zorluklara aldırmadan yoluna devam eder.","Karıncalar yol bilir."],"correct":"Hedefi olan kişi zorluklara aldırmadan yoluna devam eder.","source":"sorular3.docx","sourceLocation":"paragraph 189"},{"id":"tr-s3-072","stage":8,"category":"Yorumlama","text":"“Ormandaki ağaçlar baltaya karşı koyamadı; çünkü baltanın sapı kendilerindendi.” Bu sözle ne anlatılmak istenir?","answers":["Ağaçlar çok güçsüzdür.","Bazen bize zarar verenlere gücü biz kendimiz vermiş oluruz.","Balta çok keskindir.","Orman büyüktür."],"correct":"Bazen bize zarar verenlere gücü biz kendimiz vermiş oluruz.","source":"sorular3.docx","sourceLocation":"paragraph 191"},{"id":"tr-s3-073","stage":4,"category":"Sözcükte anlam","text":"“Bu soru ağır bir yük gibi omuzlarına çöktü.” Anlatılmak istenen nedir?","answers":["Soru ağırdı.","Omuzları ağrıdı.","Soru onu çok sıkıntıya soktu.","Soruya cevap veremedi."],"correct":"Soru onu çok sıkıntıya soktu.","source":"sorular3.docx","sourceLocation":"paragraph 199"},{"id":"tr-s3-074","stage":4,"category":"Sözcükte anlam","text":"“Gözlerinin içi gülüyordu.” Anlatılmak istenen nedir?","answers":["Gözleri ağrıyordu.","Çok neşeli ve mutluydu.","Gözleri kapalıydı.","Uykusu vardı."],"correct":"Çok neşeli ve mutluydu.","source":"sorular3.docx","sourceLocation":"paragraph 201"},{"id":"tr-s3-075","stage":3,"category":"Atasözleri","text":"“Ak akçe kara gün içindir.” atasözü ne anlatır?","answers":["Para beyazdır.","Kara günler beyaz olur.","Para harcanmaz.","Biriktirilen para zor zamanlarda işe yarar."],"correct":"Biriktirilen para zor zamanlarda işe yarar.","source":"sorular3.docx","sourceLocation":"paragraph 206"},{"id":"tr-s3-076","stage":3,"category":"Atasözleri","text":"“Ne ekersen onu biçersin.” atasözü ne anlatır?","answers":["Ekin ekmek zordur.","Yaptığımız işin karşılığını görürüz.","Tarla önemlidir.","Hasat mevsimi uzundur."],"correct":"Yaptığımız işin karşılığını görürüz.","source":"sorular3.docx","sourceLocation":"paragraph 207"},{"id":"tr-s3-077","stage":3,"category":"Atasözleri","text":"“Çalma elin kapısını, çalarlar kapını.” atasözü ne anlatır?","answers":["Kapılar kilitli olmalı.","Komşuluk zordur.","Başkasına kötülük edersen sana da kötülük gelir.","Kapı çalmak yasaktır."],"correct":"Başkasına kötülük edersen sana da kötülük gelir.","source":"sorular3.docx","sourceLocation":"paragraph 208"},{"id":"tr-s3-078","stage":3,"category":"Atasözleri","text":"“Aç ayı oynamaz.” atasözü ne anlatır?","answers":["Ayılar dans eder.","Karnı aç olan kişi iş yapamaz.","Hayvanlar aç kalmamalı.","Oyun çok eğlencelidir."],"correct":"Karnı aç olan kişi iş yapamaz.","source":"sorular3.docx","sourceLocation":"paragraph 209"},{"id":"tr-s3-079","stage":3,"category":"Atasözleri","text":"“Bakarsan bağ olur, bakmazsan dağ olur.” atasözü ne anlatır?","answers":["Bağlar dağlarda olur.","Dağlar bağ olmaz.","İlgilenilen şey değer kazanır, ilgilenilmeyen boş kalır.","Bağ bakımı zordur."],"correct":"İlgilenilen şey değer kazanır, ilgilenilmeyen boş kalır.","source":"sorular3.docx","sourceLocation":"paragraph 210"},{"id":"tr-s3-080","stage":3,"category":"Atasözleri","text":"“Dost acı söyler.” atasözü ne anlatır?","answers":["Dostlar kırıcıdır.","Doğru dost, hoşa gitmese de gerçeği söyler.","Acı yemek sağlıklıdır.","Dostlar çok konuşur."],"correct":"Doğru dost, hoşa gitmese de gerçeği söyler.","source":"sorular3.docx","sourceLocation":"paragraph 211"},{"id":"tr-s3-081","stage":3,"category":"Atasözleri","text":"“Tatlı dil yılanı deliğinden çıkarır.” atasözü ne anlatır?","answers":["Yılanlar dinler.","Delikler tehlikelidir.","Nazik ve yumuşak konuşma en zor kişiyi bile ikna eder.","Tatlı yemek zararlıdır."],"correct":"Nazik ve yumuşak konuşma en zor kişiyi bile ikna eder.","source":"sorular3.docx","sourceLocation":"paragraph 212"},{"id":"tr-s3-082","stage":3,"category":"Atasözleri","text":"“Kervan yolda düzülür.” atasözü ne anlatır?","answers":["Kervanlar yolda kalır.","Yolculuk zordur.","İşe başlayınca gerekli şeyler zamanla tamamlanır.","Hazırlık gereksizdir."],"correct":"İşe başlayınca gerekli şeyler zamanla tamamlanır.","source":"sorular3.docx","sourceLocation":"paragraph 213"},{"id":"tr-s3-083","stage":3,"category":"Deyimler","text":"“Hocanın sözlerine kulak verdi.” Deyim ne anlatır?","answers":["Kulağını verdi.","Dikkatle dinledi.","Duymadı.","Bağırdı."],"correct":"Dikkatle dinledi.","source":"sorular3.docx","sourceLocation":"paragraph 218"},{"id":"tr-s3-084","stage":3,"category":"Deyimler","text":"“Geç kalıyoruz, elini çabuk tut.” Deyim ne anlatır?","answers":["Elini yıka.","Elini yavaş tut.","Acele et.","Eline dikkat et."],"correct":"Acele et.","source":"sorular3.docx","sourceLocation":"paragraph 219"},{"id":"tr-s3-085","stage":3,"category":"Deyimler","text":"“Karanlık odada bir ses duyunca yüreği ağzına geldi.” Deyim ne anlatır?","answers":["Çok korktu.","Çok yedi.","Çok güldü.","Çok yoruldu."],"correct":"Çok korktu.","source":"sorular3.docx","sourceLocation":"paragraph 220"},{"id":"tr-s3-086","stage":3,"category":"Deyimler","text":"“Sonucu duyunca ağzı açık kaldı.” Deyim ne anlatır?","answers":["Çok yemek yedi.","Uyuyakaldı.","Esnedi.","Çok şaşırdı."],"correct":"Çok şaşırdı.","source":"sorular3.docx","sourceLocation":"paragraph 221"},{"id":"tr-s3-087","stage":3,"category":"Deyimler","text":"“Kardeşim yeni yemeğe burun kıvırdı.” Deyim ne anlatır?","answers":["Beğenmedi.","Çok sevdi.","Koklayıp yedi.","Kızdı."],"correct":"Beğenmedi.","source":"sorular3.docx","sourceLocation":"paragraph 222"},{"id":"tr-s3-088","stage":3,"category":"Deyimler","text":"“Proje için hep birlikte kolları sıvadık.” Deyim ne anlatır?","answers":["Üşüdük.","Elimizi yıkadık.","Kollarımızı katladık.","Çalışmaya başladık."],"correct":"Çalışmaya başladık.","source":"sorular3.docx","sourceLocation":"paragraph 223"},{"id":"tr-s3-089","stage":3,"category":"Deyimler","text":"“Toplantıda söylediği söz yüzünden pot kırdı.” Deyim ne anlatır?","answers":["Yersiz söz ya da davranışla gaf yaptı.","Tencere kırdı.","Sinirlendi.","Hediye aldı."],"correct":"Yersiz söz ya da davranışla gaf yaptı.","source":"sorular3.docx","sourceLocation":"paragraph 224"},{"id":"tr-s3-090","stage":3,"category":"Deyimler","text":"“Karne gününü bekleyen çocuğun etekleri zil çalıyordu.” Deyim ne anlatır?","answers":["Çok üşüyordu.","Çok sevinçliydi.","Zil sesini duydu.","Eteği vardı."],"correct":"Çok sevinçliydi.","source":"sorular3.docx","sourceLocation":"paragraph 225"},{"id":"tr-s3-091","stage":3,"category":"Deyimler","text":"“Müşteriyi göz boyayarak kandırdı.” Deyim ne anlatır?","answers":["Gözünü boyadı.","Gösterişle gerçeği gizleyip aldattı.","Ona hediye verdi.","Tablo çizdi."],"correct":"Gösterişle gerçeği gizleyip aldattı.","source":"sorular3.docx","sourceLocation":"paragraph 226"},{"id":"tr-s3-092","stage":3,"category":"Deyimler","text":"“Haksızlığa uğrayan adam, yıllarca ona diş bilemişti.” Deyim ne anlatır?","answers":["Dişlerini fırçaladı.","Ona teşekkür etti.","Ona kızıp intikam almayı bekledi.","Dişçiye gitti."],"correct":"Ona kızıp intikam almayı bekledi.","source":"sorular3.docx","sourceLocation":"paragraph 227"},{"id":"tr-s3-093","stage":6,"category":"Kelimede yapı","text":"“Yolcular” sözcüğünün kökü ve ek sayısı hangisidir?","answers":["yol – 2 ek","yolcu – 2 ek","yolcular – 1 ek","yol – 3 ek"],"correct":"yol – 2 ek","source":"sorular3.docx","sourceLocation":"paragraph 233"},{"id":"tr-s3-094","stage":6,"category":"Kelimede yapı","text":"“Çalışkanlığımızdan” sözcüğünün kökü ve ek sayısı hangisidir?","answers":["çalışkan – 3 ek","çalış – 4 ek","çalış – 3 ek","çalışkanlık – 2 ek"],"correct":"çalış – 4 ek","source":"sorular3.docx","sourceLocation":"paragraph 235"},{"id":"tr-s3-095","stage":6,"category":"Kelimede yapı","text":"“Dinleyiciler” sözcüğünün kökü hangisidir?","answers":["dinleyici","dinleyi","dinle","din"],"correct":"dinle","source":"sorular3.docx","sourceLocation":"paragraph 237"},{"id":"tr-s3-096","stage":6,"category":"Kelimede yapı","text":"“Yazarlarımızdan” sözcüğünün kökü ve ek sayısı hangisidir?","answers":["yaz – 4 ek","yazar – 3 ek","yaz – 3 ek","yazarlar – 2 ek"],"correct":"yaz – 4 ek","source":"sorular3.docx","sourceLocation":"paragraph 238"},{"id":"tr-s3-097","stage":3,"category":"Şiir ve uyak","text":"“Karlar yağdı dağlara, / Kuşlar kondu bağlara.” Uyaklı sözcükler hangileridir?","answers":["karlar – kuşlar","yağdı – kondu","dağlara – bağlara","karlar – dağlara"],"correct":"dağlara – bağlara","source":"sorular3.docx","sourceLocation":"paragraph 242"},{"id":"tr-s3-098","stage":3,"category":"Şiir ve uyak","text":"“Yaz geldi çiçek açtı, / Bahçelere sevinç saçtı.” Uyaklı sözcükler hangileridir?","answers":["yaz – bahçelere","çiçek – sevinç","açtı – saçtı","geldi – açtı"],"correct":"açtı – saçtı","source":"sorular3.docx","sourceLocation":"paragraph 246"},{"id":"tr-s3-099","stage":5,"category":"Anlatım bozukluğu","text":"Hangisinde aynı anlam gereksiz yere tekrarlanmıştır?","answers":["Çocuk, küçücük ufak bir kediyi sevdi.","Gökyüzü masmaviydi.","Kuşlar ağaçta ötüyordu.","Annem çay demledi."],"correct":"Çocuk, küçücük ufak bir kediyi sevdi.","source":"sorular3.docx","sourceLocation":"paragraph 261"},{"id":"tr-s3-100","stage":3,"category":"Sözcük türleri","text":"“Yeşil yapraklar rüzgârda sallandı.” cümlesindeki sıfat hangisidir?","answers":["yapraklar","rüzgârda","yeşil","sallandı"],"correct":"yeşil","source":"sorular3.docx","sourceLocation":"paragraph 266"},{"id":"tr-s3-101","stage":3,"category":"Sözcük türleri","text":"Hangi cümlede birden fazla sıfat vardır?","answers":["Mavi kalem masada.","Kırmızı ve yeşil kalemler çantada.","Ali okula gitti.","Kitap masada."],"correct":"Kırmızı ve yeşil kalemler çantada.","source":"sorular3.docx","sourceLocation":"paragraph 269"},{"id":"tr-s3-102","stage":3,"category":"Sözcük türleri","text":"Hangi cümlede “güzel” sözcüğü sıfat değildir?","answers":["Güzel manzaraya baktık.","Güzel bir elbise aldı.","Kız güzel yazıyor.","Güzel ev satıldı."],"correct":"Kız güzel yazıyor.","source":"sorular3.docx","sourceLocation":"paragraph 270"},{"id":"tr-s3-103","stage":3,"category":"Sözcük türleri","text":"Hangisinde “kaç?” sorusuna cevap veren sıfat vardır?","answers":["Mavi gömlek","Şu araba","Altı kardeş","Hızlı tren"],"correct":"Altı kardeş","source":"sorular3.docx","sourceLocation":"paragraph 271"},{"id":"tr-s3-104","stage":3,"category":"Sözcük türleri","text":"Sıfatın özelliği hangisidir?","answers":["İsmin yerini tutar.","İşi bildirir.","Cümleyi bitirir.","İsmi niteler veya belirtir."],"correct":"İsmi niteler veya belirtir.","source":"sorular3.docx","sourceLocation":"paragraph 273"},{"id":"tr-s3-105","stage":3,"category":"Sözcük türleri","text":"Hangi sözcük hem sıfat hem isim olarak kullanılabilir?","answers":["koşmak","kırmızı","evde","gelir"],"correct":"kırmızı","source":"sorular3.docx","sourceLocation":"paragraph 274"},{"id":"tr-s3-106","stage":3,"category":"Sözcük türleri","text":"“Ali parkta futbol oynuyor.” cümlesindeki fiil hangisidir?","answers":["Ali","parkta","futbol","oynuyor"],"correct":"oynuyor","source":"sorular3.docx","sourceLocation":"paragraph 278"},{"id":"tr-s3-107","stage":3,"category":"Sözcük türleri","text":"Hangisinde “ekmek” sözcüğü fiildir?","answers":["Ekmek sıcaktı.","Fırından ekmek aldık.","Tarlaya buğday ekmek için gitti.","Ekmek bayat kalmış."],"correct":"Tarlaya buğday ekmek için gitti.","source":"sorular3.docx","sourceLocation":"paragraph 284"},{"id":"tr-s3-108","stage":6,"category":"Kelimede yapı","text":"Hangisinde isimden isim türetilmiştir?","answers":["okumak","yazıcı","gelmek","sütçü"],"correct":"sütçü","source":"sorular3.docx","sourceLocation":"paragraph 292"},{"id":"tr-s3-109","stage":6,"category":"Kelimede yapı","text":"Hangisinde fiilden isim türetilmiştir?","answers":["kitaplık","balıkçı","yazıcı","göz"],"correct":"yazıcı","source":"sorular3.docx","sourceLocation":"paragraph 293"},{"id":"tr-s3-110","stage":6,"category":"Kelimede yapı","text":"Hangisinde yapım eki vardır?","answers":["çocuklar","okuldan","masalar","sulu"],"correct":"sulu","source":"sorular3.docx","sourceLocation":"paragraph 294"},{"id":"tr-s3-111","stage":6,"category":"Kelimede yapı","text":"Hangisi yapım eki değildir?","answers":["-lık","-sız","-cı","-ler"],"correct":"-ler","source":"sorular3.docx","sourceLocation":"paragraph 295"},{"id":"tr-s3-112","stage":6,"category":"Kelimede yapı","text":"Hangisinde getirilen ek yeni anlamlı sözcük türetmemiştir?","answers":["göz → gözlük","süt → sütçü","ev → evler","tuz → tuzluk"],"correct":"ev → evler","source":"sorular3.docx","sourceLocation":"paragraph 298"},{"id":"tr-s3-113","stage":6,"category":"Kelimede yapı","text":"Hangisinde yalnızca çekim ekleri vardır?","answers":["kalemlikte","sütçünün","çocuklarımız","gözlükçüyü"],"correct":"çocuklarımız","source":"sorular3.docx","sourceLocation":"paragraph 306"},{"id":"tr-s3-114","stage":6,"category":"Kelimede yapı","text":"Hangi sözcükte iyelik eki yoktur?","answers":["kalemim","okulumuz","kitabınız","masalar"],"correct":"masalar","source":"sorular3.docx","sourceLocation":"paragraph 310"},{"id":"tr-s3-115","stage":4,"category":"Cümlede anlam","text":"Hangisi amaç bildirir?","answers":["Yorgun olduğu için yattı.","Sağlıklı beslenmek için meyve yer.","Çalışırsa kazanır.","Hastalanınca eve gitti."],"correct":"Sağlıklı beslenmek için meyve yer.","source":"sorular3.docx","sourceLocation":"paragraph 317"},{"id":"tr-s3-116","stage":4,"category":"Cümlede anlam","text":"Hangisinde sebep–sonuç ilişkisi yoktur?","answers":["Üşüdüğü için ceket giydi.","Başarılı olunca ödül aldı.","Ali ve Veli arkadaştır.","Para biriktirdiği için bisiklet aldı."],"correct":"Ali ve Veli arkadaştır.","source":"sorular3.docx","sourceLocation":"paragraph 319"},{"id":"tr-s3-117","stage":5,"category":"Cümlede anlam","text":"“Yağmur yağarsa maç ertelenir; bu yüzden bilet parası iade edilir.” cümlesinde hangi anlam ilişkileri vardır?","answers":["Amaç ve sebep","Zıtlık ve amaç","Benzerlik ve koşul","Koşul ve sonuç"],"correct":"Koşul ve sonuç","source":"sorular3.docx","sourceLocation":"paragraph 322"},{"id":"tr-s3-118","stage":5,"category":"Paragrafta anlam","text":"“Mehmet, maça gitmeden önce ödevlerini bitirdi.” Hangisi çıkarılamaz?","answers":["Ödevler maçtan önce bitti.","Mehmet ödevini bitirdi.","Mehmet maçı kazandı.","Mehmet’in ödevi vardı."],"correct":"Mehmet maçı kazandı.","source":"sorular3.docx","sourceLocation":"paragraph 327"},{"id":"tr-s3-119","stage":5,"category":"Paragrafta anlam","text":"“Kitap fuarı bu yıl hafta sonu da açık kalacak.” Hangisi çıkarılamaz?","answers":["Fuar hafta sonu gezilebilir.","Fuar bu yıl düzenleniyor.","Fuar yalnızca hafta içi açıktır.","Fuar kitaplarla ilgilidir."],"correct":"Fuar yalnızca hafta içi açıktır.","source":"sorular3.docx","sourceLocation":"paragraph 330"},{"id":"tr-s3-120","stage":5,"category":"Paragrafta anlam","text":"“Bu şehirde bisiklet yolları yapılınca trafik yoğunluğu azaldı.” Hangisi çıkarılamaz?","answers":["Bisiklet yolları yapıldı.","Trafik yoğunluğu azaldı.","Bütün şehirlerde bisiklet yolu zorunlu olmalıdır.","İki durum arasında ilişki kurulmuştur."],"correct":"Bütün şehirlerde bisiklet yolu zorunlu olmalıdır.","source":"sorular3.docx","sourceLocation":"paragraph 332"},{"id":"tr-s3-121","stage":6,"category":"Paragrafta anlam","text":"“Yazar, romanında yalnızca bir günü anlatmış; fakat bu bir gün kahramanın hayatını değiştirmiştir.” Hangisi çıkarılamaz?","answers":["Roman bir günü anlatır.","O gün önemlidir.","Kahraman bundan sonra hep mutsuz yaşamıştır.","Kahramanın hayatı değişmiştir."],"correct":"Kahraman bundan sonra hep mutsuz yaşamıştır.","source":"sorular3.docx","sourceLocation":"paragraph 334"},{"id":"tr-s3-122","stage":5,"category":"Çıkarım","text":"“Ali sabah erkenden kalkıp spor yapıyor, akşamları ise kitap okuyor.” Hangisi çıkarılabilir?","answers":["Ali tembeldir.","Ali düzenli bir yaşam sürüyor.","Ali spor sevmez.","Ali okula gitmez."],"correct":"Ali düzenli bir yaşam sürüyor.","source":"sorular3.docx","sourceLocation":"paragraph 337"},{"id":"tr-s3-123","stage":5,"category":"Çıkarım","text":"“Marketlerde poşet ücretli olunca birçok kişi bez çanta kullanmaya başladı.” Hangisi çıkarılabilir?","answers":["Poşetler bedavadır.","Bez çanta yasaklanmıştır.","Poşetin ücretli olması bez çanta kullanımını artırmıştır.","Marketler kapanmıştır."],"correct":"Poşetin ücretli olması bez çanta kullanımını artırmıştır.","source":"sorular3.docx","sourceLocation":"paragraph 338"},{"id":"tr-s3-124","stage":5,"category":"Çıkarım","text":"“Ayşe’nin odası düzenliydi, kitapları alfabetik sıralanmıştı.” Hangisi çıkarılabilir?","answers":["Ayşe dağınık biridir.","Ayşe kitap okumaz.","Ayşe’nin odası boştur.","Ayşe düzenli biridir."],"correct":"Ayşe düzenli biridir.","source":"sorular3.docx","sourceLocation":"paragraph 339"},{"id":"tr-s3-125","stage":5,"category":"Çıkarım","text":"“Sınavdan önce her gün tekrar yapan Deniz, soruları kolaylıkla yanıtladı.” Hangisi çıkarılabilir?","answers":["Sınav iptal edildi.","Deniz hiç çalışmadı.","Düzenli tekrar Deniz’e başarı sağlamıştır.","Sorular çok kolaydı."],"correct":"Düzenli tekrar Deniz’e başarı sağlamıştır.","source":"sorular3.docx","sourceLocation":"paragraph 341"},{"id":"tr-s3-126","stage":5,"category":"Çıkarım","text":"“Bu kavşakta kazalar arttığı için trafik ışığı konuldu.” Hangisi çıkarılabilir?","answers":["Işık kazaları artırdı.","Kavşak kapatıldı.","Önce kazalar vardı.","Kazalar hiç olmadı."],"correct":"Önce kazalar vardı.","source":"sorular3.docx","sourceLocation":"paragraph 342"},{"id":"tr-s3-127","stage":5,"category":"Çıkarım","text":"“Maçın son dakikasında golü yiyen takımın oyuncuları yere çöktü.” Hangisi çıkarılabilir?","answers":["Oyuncular sevindi.","Maç yapılmadı.","Gol atan takım kaybetti.","Oyuncular üzüldü."],"correct":"Oyuncular üzüldü.","source":"sorular3.docx","sourceLocation":"paragraph 343"},{"id":"tr-s3-128","stage":5,"category":"Çıkarım","text":"“Kütüphaneye giren herkes ses çıkarmamaya özen gösteriyordu.” Hangisi çıkarılabilir?","answers":["Kütüphane gürültülüdür.","Kütüphanede sessizlik kuralına uyulmaktadır.","Kütüphaneye kimse girmedi.","Kütüphanede kitap yoktur."],"correct":"Kütüphanede sessizlik kuralına uyulmaktadır.","source":"sorular3.docx","sourceLocation":"paragraph 344"},{"id":"tr-s3-129","stage":5,"category":"Çıkarım","text":"“Hasan’ın cüzdanını bulan temizlik görevlisi, içindeki parayı eksiksiz teslim etti.” Hangisi çıkarılabilir?","answers":["Hasan zengindir.","Görevli dürüsttür.","Para kaybolmuştur.","Görevli parayı harcamıştır."],"correct":"Görevli dürüsttür.","source":"sorular3.docx","sourceLocation":"paragraph 345"},{"id":"tr-s3-130","stage":5,"category":"Çıkarım","text":"“Şehirdeki yeşil alanlar azaldıkça hava kirliliği arttı.” Hangisi çıkarılabilir?","answers":["Yeşil alan kirliliği artırır.","Şehirde kirlilik azaldı.","Şehir çok küçüktür.","Yeşil alanlar azalırken kirlilik artmıştır."],"correct":"Yeşil alanlar azalırken kirlilik artmıştır.","source":"sorular3.docx","sourceLocation":"paragraph 346"},{"id":"tr-s3-131","stage":6,"category":"Metin yapıları","text":"“Uzun bir yürüyüşten sonra dağın eteğine vardık. Sönmek üzere olan güneş, tepeleri kızıla boyuyordu. Hemen çadırı kurduk.” Bu parçada hangi anlatım biçimleri kullanılmıştır?","answers":["Tartışma ve açıklama","Açıklama ve betimleme","Tartışma ve betimleme","Öyküleme ve betimleme"],"correct":"Öyküleme ve betimleme","source":"sorular3.docx","sourceLocation":"paragraph 358"},{"id":"tr-s3-132","stage":4,"category":"Yazım kuralları","text":"Hangisinde “de” bağlaçtır?","answers":["Evde kimse yoktu.","Sende bir kitap var.","Ben de sinemaya gideceğim.","Masada duruyor."],"correct":"Ben de sinemaya gideceğim.","source":"sorular3.docx","sourceLocation":"paragraph 361"},{"id":"tr-s3-133","stage":4,"category":"Yazım kuralları","text":"Hangisinde “ki” ilgi ekidir?","answers":["Sana dedim ki gelme.","Duvardaki resim güzel.","Öyle yorgunum ki konuşamam.","Biliyorsun ki zor."],"correct":"Duvardaki resim güzel.","source":"sorular3.docx","sourceLocation":"paragraph 363"},{"id":"tr-s3-134","stage":4,"category":"Yazım kuralları","text":"Hangisinde “ki” ayrı yazılmalıdır?","answers":["Sınıftaki öğrenciler","Yarınki sınav","Bahçedeki çiçekler","Çok yoruldum ki konuşamıyorum"],"correct":"Çok yoruldum ki konuşamıyorum","source":"sorular3.docx","sourceLocation":"paragraph 364"},{"id":"tr-s3-135","stage":4,"category":"Yazım kuralları","text":"Hangisinde yazım yanlışı vardır?","answers":["Biz de gideriz.","Evde yemek yedik.","Yarın da gelirim.","Sende gelirsin."],"correct":"Sende gelirsin.","source":"sorular3.docx","sourceLocation":"paragraph 365"},{"id":"tr-s3-136","stage":4,"category":"Yazım kuralları","text":"Hangisinde “-de” bulunma ekidir?","answers":["Sen de gel.","Ben de geleceğim.","O da gelsin.","Kitap sende kalmış."],"correct":"Kitap sende kalmış.","source":"sorular3.docx","sourceLocation":"paragraph 366"},{"id":"tr-s3-137","stage":4,"category":"Noktalama","text":"Üç nokta hangi durumda kullanılır?","answers":["Cümle yarım bırakıldığında","Soru sorulduğunda","Sıralama yapılırken","Tarih yazarken"],"correct":"Cümle yarım bırakıldığında","source":"sorular3.docx","sourceLocation":"paragraph 376"},{"id":"tr-s3-138","stage":4,"category":"Noktalama","text":"Hangisinde iki nokta yanlış kullanılmıştır?","answers":["Gerekli malzemeler: kâğıt, makas, yapıştırıcı.","Annem şöyle dedi: “Erken gel.”","Dün: eve geldim.","Konu: Çevre"],"correct":"Dün: eve geldim.","source":"sorular3.docx","sourceLocation":"paragraph 378"},{"id":"tr-s3-139","stage":4,"category":"Noktalama","text":"Hangisinin sonuna soru işareti konmaz?","answers":["Kaç yaşındasın","Nereye gidiyorsun","Annem nereye gittiğimi sordu","Bu çanta senin mi"],"correct":"Annem nereye gittiğimi sordu","source":"sorular3.docx","sourceLocation":"paragraph 381"},{"id":"tr-s3-140","stage":7,"category":"Ses bilgisi","text":"Hangisi yanlış yazılmıştır?","answers":["ağaçta","evde","sınıfda","kitapta"],"correct":"sınıfda","source":"sorular3.docx","sourceLocation":"paragraph 388"},{"id":"tr-s3-141","stage":7,"category":"Ses bilgisi","text":"Hangisinde ünlü daralması yoktur?","answers":["bekliyor","dinliyor","okuyor","söylüyor"],"correct":"okuyor","source":"sorular3.docx","sourceLocation":"paragraph 391"},{"id":"tr-s3-142","stage":7,"category":"Ses bilgisi","text":"Hangisinde ünlü düşmesi yoktur?","answers":["ağız → ağzı","şehir → şehri","fikir → fikri","kalem → kalemi"],"correct":"kalem → kalemi","source":"sorular3.docx","sourceLocation":"paragraph 392"},{"id":"tr-s3-143","stage":8,"category":"Çıkarım","text":"“Yalnızca 10 yaşından küçük çocuklar ücretsiz girer. Ece ücretsiz girdi.” Hangisi kesin doğrudur?","answers":["Ece 12 yaşındadır.","Ece yetişkindir.","Ece 10 yaşından küçüktür.","Ece bilet almıştır."],"correct":"Ece 10 yaşından küçüktür.","source":"sorular3.docx","sourceLocation":"paragraph 402"},{"id":"tr-s3-144","stage":8,"category":"Çıkarım","text":"“Bütün kediler memelidir. Pamuk memeli değildir.” Hangisi kesin doğrudur?","answers":["Pamuk bir kedidir.","Pamuk bir kedi değildir.","Pamuk bir köpektir.","Pamuk yaşıyordur."],"correct":"Pamuk bir kedi değildir.","source":"sorular3.docx","sourceLocation":"paragraph 405"},{"id":"tr-s3-145","stage":8,"category":"Çıkarım","text":"“Ali ya evde ya okuldadır. Ali evde değil.” Hangisi kesin doğrudur?","answers":["Ali parktadır.","Ali evdedir.","Ali okuldadır.","Ali yoldadır."],"correct":"Ali okuldadır.","source":"sorular3.docx","sourceLocation":"paragraph 406"},{"id":"tr-s3-146","stage":7,"category":"Yorumlama","text":"“Fidan eğri büyürse ağaç da eğri olur.” sözüyle ne anlatılmak istenir?","answers":["Fidanlar eğridir.","Ağaçlar eğilir.","Küçük yaşta edinilen yanlış alışkanlıklar kalıcı olur.","Ağaç dikmek zordur."],"correct":"Küçük yaşta edinilen yanlış alışkanlıklar kalıcı olur.","source":"sorular3.docx","sourceLocation":"paragraph 409"},{"id":"tr-s3-147","stage":7,"category":"Yorumlama","text":"“Dalgalara kafa tutan kayalar, yıllar geçtikçe şekillenir ama yıkılmaz.” sözüyle ne anlatılmak istenir?","answers":["Zorluklarla mücadele eden kişi güçlenir.","Kayalar yumuşaktır.","Dalgalar tehlikelidir.","Denizden uzak durulmalıdır."],"correct":"Zorluklarla mücadele eden kişi güçlenir.","source":"sorular3.docx","sourceLocation":"paragraph 410"},{"id":"tr-s3-148","stage":7,"category":"Yorumlama","text":"“Merdivenin her basamağı bir öncekine basarak çıkılır.” sözüyle ne anlatılmak istenir?","answers":["Merdivenler tehlikelidir.","Merdiven çıkmak sağlıklıdır.","Yüksek yerler güzeldir.","Başarı, adım adım ilerlemekle gelir."],"correct":"Başarı, adım adım ilerlemekle gelir.","source":"sorular3.docx","sourceLocation":"paragraph 411"},{"id":"tr-s3-149","stage":7,"category":"Yorumlama","text":"“Tek bir mum karanlığı yok edemez; ama birçok mum odayı aydınlatır.” sözüyle ne anlatılmak istenir?","answers":["Mum pahalıdır.","Karanlık korkutucudur.","Birlikte hareket edilince güç artar.","Odalar aydınlık olmalıdır."],"correct":"Birlikte hareket edilince güç artar.","source":"sorular3.docx","sourceLocation":"paragraph 413"},{"id":"tr-s3-150","stage":7,"category":"Yorumlama","text":"“Bir çiçeğin açması için güneş kadar yağmur da gerekir.” sözüyle ne anlatılmak istenir?","answers":["Çiçekler çok su ister.","Yağmur güneşten önemlidir.","Çiçekler bahçede açar.","Güzel sonuçlar için zorluklar da gereklidir."],"correct":"Güzel sonuçlar için zorluklar da gereklidir.","source":"sorular3.docx","sourceLocation":"paragraph 414"},{"id":"tr-s3-151","stage":8,"category":"Yorumlama","text":"“Küçük kız, yaralı kuşu eve getirdi, günlerce baktı. Kuş iyileşince onu salıverdi.” Bu öyküden hangi ders çıkar?","answers":["Kuşlar eve girer.","Kuş bakmak zordur.","Sevdiğimiz varlığa özgürlüğünü vermek de sevginin bir parçasıdır.","Yaralı hayvan evde kalmalıdır."],"correct":"Sevdiğimiz varlığa özgürlüğünü vermek de sevginin bir parçasıdır.","source":"sorular3.docx","sourceLocation":"paragraph 415"},{"id":"tr-s3-152","stage":7,"category":"Yorumlama","text":"“Ağaç ne kadar yükselirse köküyle o kadar derine iner.” sözüyle ne anlatılmak istenir?","answers":["Ağaçlar hızlı büyür.","Kökler görünmez.","Büyük başarılar sağlam bir temele dayanır.","Yüksek ağaç sevilir."],"correct":"Büyük başarılar sağlam bir temele dayanır.","source":"sorular3.docx","sourceLocation":"paragraph 416"},{"id":"tr-s3-153","stage":7,"category":"Yorumlama","text":"“Kitap okumayan insan, bir gözü kapalı yaşar.” sözüyle ne anlatılmak istenir?","answers":["Gözler kitapla bozulur.","Okumayan insan dünyayı eksik görür.","Kitaplar pahalıdır.","Gözler korunmalıdır."],"correct":"Okumayan insan dünyayı eksik görür.","source":"sorular3.docx","sourceLocation":"paragraph 417"},{"id":"tr-s3-154","stage":7,"category":"Yorumlama","text":"“Hata yapmaktan korkan, hiçbir şey öğrenemez.” sözüyle ne anlatılmak istenir?","answers":["Hatalar cezalandırılmalıdır.","Hata yapmak kötüdür.","Öğrenmek kolaydır.","Hatalar öğrenmenin doğal bir parçasıdır."],"correct":"Hatalar öğrenmenin doğal bir parçasıdır.","source":"sorular3.docx","sourceLocation":"paragraph 418"},{"id":"tr-s3-155","stage":5,"category":"Sözcükte anlam","text":"“Tatil günleri su gibi aktı.” cümlesindeki “su gibi aktı” ne anlatır?","answers":["Su döküldü.","Hızla geçti.","Yavaş geçti.","Yağmur yağdı."],"correct":"Hızla geçti.","source":"sorular3.docx","sourceLocation":"paragraph 425"},{"id":"tr-s3-156","stage":5,"category":"Sözcükte anlam","text":"“Haber, kalbine buz gibi çöktü.” cümlesindeki “kalbine buz gibi çöktü” ne anlatır?","answers":["Üşüdü.","Kalbi ağrıdı.","Kalbi durdu.","Büyük bir üzüntü ve korku hissetti."],"correct":"Büyük bir üzüntü ve korku hissetti.","source":"sorular3.docx","sourceLocation":"paragraph 426"},{"id":"tr-s3-157","stage":5,"category":"Sözcükte anlam","text":"“O, benim başımın üstünde yeri olan biridir.” cümlesindeki “başımın üstünde yeri olan” ne anlatır?","answers":["Başıma konmuştur.","Çok değer verdiğim, saygı duyduğum kişidir.","Yüksektedir.","Uzun boyludur."],"correct":"Çok değer verdiğim, saygı duyduğum kişidir.","source":"sorular3.docx","sourceLocation":"paragraph 429"},{"id":"tr-s3-158","stage":5,"category":"Sözcükte anlam","text":"“Yemeği görünce yüzü ekşidi.” cümlesindeki “yüzü ekşidi” ne anlatır?","answers":["Yüzü sarardı.","Yemek ekşiydi.","Hoşnutsuzluğunu belli etti.","Çok sevindi."],"correct":"Hoşnutsuzluğunu belli etti.","source":"sorular3.docx","sourceLocation":"paragraph 430"},{"id":"tr-s3-159","stage":4,"category":"Atasözleri","text":"“Her yiğidin bir yoğurt yiyişi vardır.” atasözü ne anlatır?","answers":["Yoğurt sağlıklıdır.","Yiğitler yoğurt sever.","Yoğurt yenmeden uyunmaz.","Herkesin işi yapış biçimi farklıdır."],"correct":"Herkesin işi yapış biçimi farklıdır.","source":"sorular3.docx","sourceLocation":"paragraph 433"},{"id":"tr-s3-160","stage":4,"category":"Atasözleri","text":"“Bin bilsen de bir bilene danış.” atasözü ne anlatır?","answers":["Çok bilen danışmamalıdır.","Çok bilgili olsak da deneyimli birine danışmak gerekir.","Bilmek zordur.","Bin kişiye sormalıdır."],"correct":"Çok bilgili olsak da deneyimli birine danışmak gerekir.","source":"sorular3.docx","sourceLocation":"paragraph 434"},{"id":"tr-s3-161","stage":4,"category":"Atasözleri","text":"“İşleyen demir ışıldar.” atasözü ne anlatır?","answers":["Demir parlar.","Madenler değerlidir.","Çalışan kişi gelişir, hep taze kalır.","Demir pastan korunur."],"correct":"Çalışan kişi gelişir, hep taze kalır.","source":"sorular3.docx","sourceLocation":"paragraph 435"},{"id":"tr-s3-162","stage":4,"category":"Atasözleri","text":"“Sabreden derviş muradına ermiş.” atasözü ne anlatır?","answers":["Dervişler mutludur.","Dervişler sabırlıdır.","Murat bir isimdir.","Sabırlı davranan kişi istediğine ulaşır."],"correct":"Sabırlı davranan kişi istediğine ulaşır.","source":"sorular3.docx","sourceLocation":"paragraph 436"},{"id":"tr-s3-163","stage":4,"category":"Atasözleri","text":"“Rüzgâr eken fırtına biçer.” atasözü ne anlatır?","answers":["Ekin ekmek zordur.","Kötülük yapan, daha büyük bir zararla karşılaşır.","Rüzgâr çok eser.","Fırtınalar tehlikelidir."],"correct":"Kötülük yapan, daha büyük bir zararla karşılaşır.","source":"sorular3.docx","sourceLocation":"paragraph 437"},{"id":"tr-s3-164","stage":4,"category":"Atasözleri","text":"“Bir musibet bin nasihatten yeğdir.” atasözü ne anlatır?","answers":["Nasihat kötüdür.","Musibet çok olur.","Başa gelen kötü olay insana en iyi dersi verir.","Nasihat etmemeli."],"correct":"Başa gelen kötü olay insana en iyi dersi verir.","source":"sorular3.docx","sourceLocation":"paragraph 438"},{"id":"tr-s3-165","stage":4,"category":"Atasözleri","text":"“Gülme komşuna, gelir başına.” atasözü ne anlatır?","answers":["Komşular gülmemeli.","Komşuyla konuşulmaz.","Başkasının başına gelen kötü olaya gülmemeli.","Gülmek yasaktır."],"correct":"Başkasının başına gelen kötü olaya gülmemeli.","source":"sorular3.docx","sourceLocation":"paragraph 440"},{"id":"tr-s3-166","stage":4,"category":"Atasözleri","text":"“Ağacı kurt, insanı dert yer.” atasözü ne anlatır?","answers":["Kurtlar ağaç yer.","Ağaçlar hastalanır.","Dertler insanı yıpratır.","İnsan ağaçtan beslenir."],"correct":"Dertler insanı yıpratır.","source":"sorular3.docx","sourceLocation":"paragraph 442"},{"id":"tr-s3-167","stage":4,"category":"Deyimler","text":"“Gürültüyü duyunca kulak kabarttı.” Deyim ne anlatır?","answers":["Kulağını şişirdi.","Duymak istemedi.","Bağırdı.","Dikkatle dinlemeye çalıştı."],"correct":"Dikkatle dinlemeye çalıştı.","source":"sorular3.docx","sourceLocation":"paragraph 445"},{"id":"tr-s3-168","stage":4,"category":"Deyimler","text":"“Gazeteye göz attım.” Deyim ne anlatır?","answers":["Gözümü attım.","Şöyle bir bakıp geçtim.","Gazeteyi attım.","Gazete okumadım."],"correct":"Şöyle bir bakıp geçtim.","source":"sorular3.docx","sourceLocation":"paragraph 446"},{"id":"tr-s3-169","stage":4,"category":"Deyimler","text":"“Büyük hayaller kursa da ayakları yere basıyordu.” Deyim ne anlatır?","answers":["Yürüyordu.","Hayalperestti.","Gerçekçi davranıyordu.","Yerde oturuyordu."],"correct":"Gerçekçi davranıyordu.","source":"sorular3.docx","sourceLocation":"paragraph 447"},{"id":"tr-s3-170","stage":4,"category":"Deyimler","text":"“Eli açık biri olduğu için herkese yardım ederdi.” Deyim ne anlatır?","answers":["Eli yaralıydı.","Tembeldi.","Elini açardı.","Cömertti."],"correct":"Cömertti.","source":"sorular3.docx","sourceLocation":"paragraph 448"},{"id":"tr-s3-171","stage":4,"category":"Deyimler","text":"“Arkadaşını korumak için gözünü budaktan sakınmadı.” Deyim ne anlatır?","answers":["Ağaçtan düştü.","Zorlukları göze alarak cesurca davrandı.","Gözlerini korudu.","Ağaca tırmandı."],"correct":"Zorlukları göze alarak cesurca davrandı.","source":"sorular3.docx","sourceLocation":"paragraph 449"},{"id":"tr-s3-172","stage":4,"category":"Deyimler","text":"“Yanlış cevabı verince yüzü kızardı.” Deyim ne anlatır?","answers":["Utandı.","Üşüdü.","Sinirlendi.","Hastalandı."],"correct":"Utandı.","source":"sorular3.docx","sourceLocation":"paragraph 451"},{"id":"tr-s3-173","stage":4,"category":"Deyimler","text":"“Kötü haberi duyunca ağzını bıçak açmadı.” Deyim ne anlatır?","answers":["Ağzı yaralandı.","Çok konuştu.","Bıçak kullandı.","Üzüntüden hiç konuşmadı."],"correct":"Üzüntüden hiç konuşmadı.","source":"sorular3.docx","sourceLocation":"paragraph 452"},{"id":"tr-s3-174","stage":4,"category":"Deyimler","text":"“Kardeşim ağzı sıkı biridir.” Deyim ne anlatır?","answers":["Sır saklayan, konuştuklarını dışarı sızdırmayan","Çok yemek yiyen","Çok konuşan","Ağzını açmayan"],"correct":"Sır saklayan, konuştuklarını dışarı sızdırmayan","source":"sorular3.docx","sourceLocation":"paragraph 453"},{"id":"tr-s3-175","stage":4,"category":"Deyimler","text":"“Karne gününü dört gözle bekledi.” Deyim ne anlatır?","answers":["Gözlük taktı.","Bakmadı.","Büyük bir heyecan ve sabırsızlıkla bekledi.","Dört kez baktı."],"correct":"Büyük bir heyecan ve sabırsızlıkla bekledi.","source":"sorular3.docx","sourceLocation":"paragraph 454"},{"id":"tr-s3-176","stage":6,"category":"Paragrafta anlam","text":"“Sabah erken kalkanlar günlerini daha verimli geçirir. Güne erken başlamak, işleri sakin sakin yapmaya zaman bırakır.” Parçaya en uygun başlık hangisidir?","answers":["Uyku Sorunları","Kahvaltı Çeşitleri","Akşam Yürüyüşü","Erken Kalkmanın Faydaları"],"correct":"Erken Kalkmanın Faydaları","source":"sorular3.docx","sourceLocation":"paragraph 458"},{"id":"tr-s3-177","stage":6,"category":"Paragrafta anlam","text":"“Her gün küçük bir ödev yapmak, sınav günü büyük bir yük taşımaktan kurtarır. Bu yüzden çalışmayı biriktirmemeliyiz.” Ana fikir nedir?","answers":["Ödevler çok zordur.","Sınavlar kaldırılmalıdır.","Düzenli çalışmak, sonradan büyük yük oluşmasını önler.","Çalışmak yorucudur."],"correct":"Düzenli çalışmak, sonradan büyük yük oluşmasını önler.","source":"sorular3.docx","sourceLocation":"paragraph 459"},{"id":"tr-s3-178","stage":6,"category":"Paragrafta anlam","text":"“Doğada hiçbir şey boşa gitmez; yaprak toprağa karışır, toprak yeni bitkileri besler.” Ana fikir nedir?","answers":["Yapraklar sararır.","Doğada her şey bir döngü içindedir.","Toprak çok önemlidir.","Bitkiler gübre ister."],"correct":"Doğada her şey bir döngü içindedir.","source":"sorular3.docx","sourceLocation":"paragraph 460"},{"id":"tr-s3-179","stage":6,"category":"Paragrafta anlam","text":"Konu ile ana fikir arasındaki fark hangisidir?","answers":["İkisi aynı şeydir.","Konu yazarın mesajı, ana fikir parçanın başlığıdır.","Konu parçada neyden söz edildiğini, ana fikir yazarın vermek istediği mesajı gösterir.","Ana fikir yalnızca şiirde bulunur."],"correct":"Konu parçada neyden söz edildiğini, ana fikir yazarın vermek istediği mesajı gösterir.","source":"sorular3.docx","sourceLocation":"paragraph 461"},{"id":"tr-s3-180","stage":6,"category":"Paragrafta anlam","text":"“Okuma alışkanlığı kazanmak için önce ilgi duyduğumuz kitapları seçmeliyiz. Sonra her gün kısa bir süre okumak bu alışkanlığı pekiştirir.” Ana fikir nedir?","answers":["Kitaplar pahalıdır.","Uzun okumak gereklidir.","Çocuklar okumaz.","Okuma alışkanlığı, ilgiyle ve düzenli çabayla kazanılır."],"correct":"Okuma alışkanlığı, ilgiyle ve düzenli çabayla kazanılır.","source":"sorular3.docx","sourceLocation":"paragraph 462"},{"id":"tr-s3-181","stage":7,"category":"Paragrafta anlam","text":"“Köyümüzün okulu küçüktü, sınıflar kalabalıktı. Ama öğretmenlerimiz öyle sevecendi ki hiçbir eksiklik hissetmezdik.” Ana fikir nedir?","answers":["Okullar küçük olmalıdır.","Kalabalık sınıflar iyidir.","Köyde okul yoktur.","Olanaklar kısıtlı olsa da sevgi ve ilgi eksikleri tamamlar."],"correct":"Olanaklar kısıtlı olsa da sevgi ve ilgi eksikleri tamamlar.","source":"sorular3.docx","sourceLocation":"paragraph 463"},{"id":"tr-s3-182","stage":7,"category":"Paragrafta anlam","text":"“Teknoloji bize hız kazandırdı; ancak yüz yüze sohbetleri azalttı. Dengeyi bulmak bizim elimizde.” Ana fikir nedir?","answers":["Telefonlar yasaklanmalıdır.","Teknoloji dengeli kullanılmalıdır.","Sohbet etmek zordur.","Hız her şeyden önemlidir."],"correct":"Teknoloji dengeli kullanılmalıdır.","source":"sorular3.docx","sourceLocation":"paragraph 465"},{"id":"tr-s3-183","stage":7,"category":"Paragrafta anlam","text":"“Ayşe, ödülü kazanmak için değil, öğrenmenin keyfi için çalıştı. Sonunda hem bilgi hem ödül onu buldu.” Ana fikir nedir?","answers":["Ödüller önemsizdir.","Ayşe şanslıdır.","Yarışmalar zordur.","İsteyerek ve keyifle çalışmak hem öğretir hem kazandırır."],"correct":"İsteyerek ve keyifle çalışmak hem öğretir hem kazandırır.","source":"sorular3.docx","sourceLocation":"paragraph 466"}]);})();
